class Solution {
public:
    int secondsToRemoveOccurrences(string s) {
        int t = 0;
        while (s.find("01") != string::npos) {
            string ns = s;
            for (int i = 0; i + 1 < (int)s.size(); i++)
                if (s[i] == '0' && s[i+1] == '1') ns[i] = '1', ns[i+1] = '0';
            s = ns; t++;
        }
        return t;
    }
};

