class Solution {
    public int secondsToRemoveOccurrences(String s) {
        int t = 0;
        while (s.contains("01")) {
            char[] a = s.toCharArray();
            char[] ns = a.clone();
            for (int i = 0; i + 1 < a.length; i++)
                if (a[i] == '0' && a[i+1] == '1') { ns[i] = '1'; ns[i+1] = '0'; }
            s = new String(ns); t++;
        }
        return t;
    }
}

