class Solution:
    def secondsToRemoveOccurrences(self, s: str) -> int:
        ones = s.count('1')
        ans = seen = 0
        for c in s:
            if c == '1':
                seen += 1
            else:
                ans = max(ans, ones - seen)
        return ans

