class Solution {
public:
    int secondsToRemoveOccurrences(string s) {
        int ones = count(s.begin(), s.end(), '1');
        int ans = 0, seen = 0;
        for (char c : s) {
            if (c == '1') seen++;
            else ans = max(ans, ones - seen);
        }
        return ans;
    }
};

