class Solution {
    public int secondsToRemoveOccurrences(String s) {
        int ones = 0;
        for (char c : s.toCharArray()) if (c == '1') ones++;
        int ans = 0, seen = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') seen++;
            else ans = Math.max(ans, ones - seen);
        }
        return ans;
    }
}

