var secondsToRemoveOccurrences = function(s) {
    let ones = [...s].filter(c => c === '1').length;
    let ans = 0, seen = 0;
    for (const c of s) {
        if (c === '1') seen++;
        else ans = Math.max(ans, ones - seen);
    }
